"""Paired fixed-exposure semantic comparisons; programmed decoding separate."""
import argparse,gzip,json,time,numpy as np
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('learned_root',type=Path);p.add_argument('decoded_root',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();t=time.monotonic();load=lambda f:json.load(gzip.open(f));old=load(a.learned_root/'s04-current-n8192-262k-dev201/evaluation-u24576.json.gz');new=load(a.learned_root/'s11-lr-decay-n8192-196k-dev201/evaluation-u24576.json.gz');assert [(r['seed'],r['target'])for r in old['rows']]==[(r['seed'],r['target'])for r in new['rows']];a0=load(a.decoded_root/'s10-reuse-historical-matched/predictions.json.gz');a1=load(a.decoded_root/'s10-reuse-s11/predictions.json.gz');results=[];rng=np.random.default_rng(692);ix=rng.integers(0,512,(4000,512))
